const e=new IntersectionObserver((t=>t.forEach((t=>{t.isIntersecting&&(t.target.classList.add("in"),e.unobserve(t.target))}))),{threshold:.15});document.querySelectorAll(".rv").forEach((t=>e.observe(t))),document.querySelectorAll("[data-car]").forEach((e=>{e.addEventListener("click",(()=>{const t=document.getElementById(e.dataset.car);t?.scrollBy({left:420*(parseInt(e.dataset.dir)||1),behavior:"smooth"})}))}));